def shortest_unique_prefixes(words):
    root = {"count": 0, "children": {}}
    for word in words:
        node = root
        for ch in word:
            if ch not in node["children"]:
                node["children"][ch] = {"count": 0, "children": {}}
            node = node["children"][ch]
            node["count"] += 1
    result = []
    for word in words:
        node = root
        prefix_chars = []
        for ch in word:
            node = node["children"][ch]
            prefix_chars.append(ch)
            if node["count"] == 1:
                break
        result.append("".join(prefix_chars))
    return result
